
CREATE TABLE IF NOT EXISTS "MarketplaceListing"("id" TEXT PRIMARY KEY,"symbol" TEXT NOT NULL,"name" TEXT NOT NULL,"category" TEXT NOT NULL,"network" TEXT NOT NULL,"priceUsd" DECIMAL(18,8) NOT NULL,"available" DECIMAL(30,8) NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "MarketplaceOrder"("id" TEXT PRIMARY KEY,"listingId" TEXT NOT NULL,"userId" TEXT,"side" TEXT NOT NULL,"quantity" DECIMAL(30,8) NOT NULL,"priceUsd" DECIMAL(18,8) NOT NULL,"status" TEXT NOT NULL DEFAULT 'OPEN',"transactionSignature" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "RenewableProductionReading"("id" TEXT PRIMARY KEY,"assetId" TEXT NOT NULL,"energyKwh" DOUBLE PRECISION NOT NULL,"verified" BOOLEAN NOT NULL DEFAULT false,"source" TEXT,"recordedAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "WalletTransaction"("id" TEXT PRIMARY KEY,"userId" TEXT,"chain" TEXT NOT NULL,"asset" TEXT NOT NULL,"amount" DECIMAL(30,9) NOT NULL,"recipient" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'CREATED',"signature" TEXT UNIQUE,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "MarketplaceOrder_listingId_status_idx" ON "MarketplaceOrder"("listingId","status");
CREATE INDEX IF NOT EXISTS "RenewableProductionReading_assetId_recordedAt_idx" ON "RenewableProductionReading"("assetId","recordedAt");
